import{_ as t,o as a,c as i,ae as s}from"./chunks/framework.CpswWCIH.js";const u=JSON.parse('{"title":"Cloud sync OAuth setup","description":"","frontmatter":{},"headers":[],"relativePath":"cloud-sync-oauth.md","filePath":"cloud-sync-oauth.md"}'),n={name:"cloud-sync-oauth.md"};function o(r,e,l,d,p,c){return a(),i("div",null,e[0]||(e[0]=[s(`<h1 id="cloud-sync-oauth-setup" tabindex="-1">Cloud sync OAuth setup <a class="header-anchor" href="#cloud-sync-oauth-setup" aria-label="Permalink to &quot;Cloud sync OAuth setup&quot;">​</a></h1><p>Google Drive and OneDrive credentials are public native-app configuration, supplied with Dart defines at build time. <strong>Do not add a client secret</strong> to the application or repository. Access/refresh tokens are stored through <code>simple_secure_storage</code>, not preferences.</p><h2 id="google-drive" tabindex="-1">Google Drive <a class="header-anchor" href="#google-drive" aria-label="Permalink to &quot;Google Drive&quot;">​</a></h2><ol><li>In one Google Cloud project, enable <strong>Google Drive API</strong> and <strong>Google Picker API</strong>.</li><li>Create OAuth clients in that project: <ul><li><strong>Desktop app</strong> client for Linux/Windows/macOS OAuth.</li><li>Android OAuth clients for each package name and signing-certificate SHA-1 used by the shipped flavors. Android uses Google Identity Services; it does not use the desktop loopback flow.</li><li>A <strong>Web application</strong> client ID for Android&#39;s <code>serverClientId</code>.</li></ul></li><li>The account requests only <code>https://www.googleapis.com/auth/drive.file</code>. The Picker API key and Cloud project number are also required to choose a parent folder.</li><li>Restrict the Picker API key to the Google Picker API. A Web referrer restriction may not match the app&#39;s embedded <code>http://localhost/</code> Picker origin; test your chosen key restrictions on each platform.</li></ol><p>Build defines:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CIYUE_GOOGLE_DRIVE_DESKTOP_CLIENT_ID</span></span>
<span class="line"><span>CIYUE_GOOGLE_DRIVE_DESKTOP_REDIRECT_URI   # optional; default http://localhost:43824</span></span>
<span class="line"><span>CIYUE_GOOGLE_ANDROID_SERVER_CLIENT_ID     # Web application client ID</span></span>
<span class="line"><span>CIYUE_GOOGLE_PICKER_API_KEY</span></span>
<span class="line"><span>CIYUE_GOOGLE_PROJECT_NUMBER               # numeric Cloud project number, not a client ID</span></span></code></pre></div><p><code>drive.file</code> intentionally does not grant access to arbitrary existing Drive files. The Picker chooses a <strong>parent folder</strong>; Ciyue creates/uses its own <code>Ciyue</code> directory and sync files beneath it. Keep the desktop and Android OAuth clients in the same Cloud project so they represent the same app. Users should not expect Ciyue to import unrelated files merely because they are inside the chosen folder.</p><h2 id="onedrive" tabindex="-1">OneDrive <a class="header-anchor" href="#onedrive" aria-label="Permalink to &quot;OneDrive&quot;">​</a></h2><ol><li>Create a Microsoft Entra app registration for a public/native client. Do not create or ship a client secret.</li><li>Add the delegated Microsoft Graph permission <code>Files.ReadWrite</code> and request user consent as required by your tenant. The default tenant is <code>common</code>; use a tenant ID/domain to restrict sign-in if desired.</li><li>Add the platform redirects: <ul><li><strong>Mobile and desktop applications</strong> for desktop, with <code>http://localhost</code> registered. Ciyue&#39;s loopback listener defaults to port <code>43824</code>; Entra ignores the port when matching localhost redirects.</li><li><strong>Android</strong> for every Android application ID and signing certificate you distribute. Entra generates the <code>msauth://&lt;package-name&gt;/&lt;signature-hash&gt;</code> URI. Use the exact URI for the selected flavor/signing key.</li></ul></li></ol><p>Build defines:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CIYUE_MICROSOFT_CLIENT_ID</span></span>
<span class="line"><span>CIYUE_MICROSOFT_TENANT                    # optional; defaults to common</span></span>
<span class="line"><span>CIYUE_MICROSOFT_DESKTOP_REDIRECT_URI       # optional; default http://localhost:43824</span></span>
<span class="line"><span>CIYUE_MICROSOFT_ANDROID_REDIRECT_URI       # exact Entra-generated msauth:// URI</span></span></code></pre></div><p>Android application IDs are defined in <code>android/app/build.gradle.kts</code>: <code>org.eu.mumulhl.ciyue</code>, <code>.dev</code>, <code>.full</code>, and <code>.full.dev</code> (the suffixes are applied to the base ID). Register the package/signature combinations actually used for debug and release builds. The manifest callback filter uses <code>msauth</code>, the built application ID, and a <code>/</code> path prefix.</p><h2 id="build-example" tabindex="-1">Build example <a class="header-anchor" href="#build-example" aria-label="Permalink to &quot;Build example&quot;">​</a></h2><p>Pass only the defines needed for the target platform/provider. Quote values containing punctuation so the shell does not interpret them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flutter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dart-define=CIYUE_GOOGLE_DRIVE_DESKTOP_CLIENT_ID=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;...apps.googleusercontent.com&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --dart-define=CIYUE_GOOGLE_PICKER_API_KEY=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;...&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --dart-define=CIYUE_GOOGLE_PROJECT_NUMBER=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1234567890&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --dart-define=CIYUE_MICROSOFT_CLIENT_ID=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;...&#39;</span></span></code></pre></div><p>For Android, also pass <code>CIYUE_GOOGLE_ANDROID_SERVER_CLIENT_ID</code>; for OneDrive Android, pass the <code>CIYUE_MICROSOFT_ANDROID_REDIRECT_URI</code> generated for that flavor and signing certificate. OAuth credentials are currently not configured in the repository, so real account sign-in still needs an application owner to create these registrations and provide the public IDs.</p><p>The first sync remains preview-only until the user confirms. Dictionary packages remain opt-in individually; OAuth authorization itself does not upload user data.</p><p>Official setup references:</p><ul><li><a href="https://developers.google.com/workspace/drive/api/guides/api-specific-auth" target="_blank" rel="noreferrer">Google Drive API scopes</a></li><li><a href="https://developers.google.com/workspace/drive/picker/guides/web-picker" target="_blank" rel="noreferrer">Google Picker integration</a></li><li><a href="https://pub.dev/packages/google_sign_in_android#integration" target="_blank" rel="noreferrer">Google Sign-In Android integration</a></li><li><a href="https://learn.microsoft.com/en-us/entra/identity-platform/reply-url" target="_blank" rel="noreferrer">Microsoft redirect URI guidance</a></li><li><a href="https://learn.microsoft.com/en-us/entra/identity-platform/how-to-add-redirect-uri" target="_blank" rel="noreferrer">Microsoft Android redirect URI setup</a></li></ul>`,19)]))}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
